package com.jnapanam.sportszone.membership.dto; import com.jnapanam.sportszone.membership.model.MembershipPlan; import java.math.BigDecimal; import java.util.*;
public record MembershipPlanResponse(UUID id,String code,String name,String description,int durationDays,BigDecimal price,Integer dailyBookingLimit,Integer monthlyBookingLimit,String status,List<String> sportCodes){public static MembershipPlanResponse from(MembershipPlan p){return new MembershipPlanResponse(p.getId(),p.getCode(),p.getName(),p.getDescription(),p.getDurationDays(),p.getPrice(),p.getDailyBookingLimit(),p.getMonthlyBookingLimit(),p.getStatus().name(),p.getSports().stream().map(s->s.getCode()).sorted().toList());}}
